142	    /** Change a DRAFT claim's amount, date, note and external reference (blank: none; one another
143	     *  claim on the sheet already uses, without regard to case, is refused); a missing date takes the
144	     *  sheet's entry date, else its today. Any
145	     *  other claim is refused: an OPEN one is changed by voiding it and adding a new one. */
146	    @Transactional
147	    public Claim update(String sheetId, String user, Long personId, Long id, BigDecimal amount, LocalDate date,
148	            String note, String corrects, String ref, String tags) {
149	        Person person = person(sheetId, personId);
150	        corrects = numberOf(corrects);
151	        Claim claim = claims.findByIdAndSheetIdAndPersonId(id, sheetId, personId)
152	                .orElseThrow(() -> new NoSuchElementException("No claim " + id + " for person " + personId));
153	        if (claim.getStatus() != ClaimStatus.DRAFT) {
154	            throw new ClaimNotEditableException(claim.getStatus());
155	        }
156	        if (claim.lockedAgainst(user)) {
157	            throw new ClaimLockedException(claim.getLockedBy());
158	        }
159	        LocalDate on = date != null ? date : settings.defaultClaimDate(sheetId);
160	        refuseClosed(sheetId, claim.getDueBy());
161	        refuseRetired(person, on);
162	        refuseBadCorrection(sheetId, personId, amount, corrects);
163	        ref = refOf(ref);
164	        refuseRefInUse(sheetId, ref, claim.getId());
165	        claim.setAmount(scaled(amount));
166	        claim.setRef(ref);
167	        claim.setTags(tagsOf(tags));
168	        claim.setCorrects(corrects);
169	        claim.setDate(on);
170	        claim.setNote(noteOf(note));
171	        claim.setLockedBy(null);
172	        claim.setEditedBy(user);
173	        Claim saved = claims.saveAndFlush(claim);
174	        useTags(sheetId, saved);
175	        record("CLAIM_EDITED", sheetId, user, person, saved);
176	        return saved;
177	    }
