179	    /** Open a claim's editor: lock the claim to the user until they save or cancel it, or the
180	     *  sheet's today changes. A claim that is not a DRAFT, is dated in a closed period, or is locked
181	     *  by another user's editor is refused and takes no lock. */
182	    @Transactional
183	    public Claim lock(String sheetId, String user, Long personId, Long id) {
184	        person(sheetId, personId);
185	        // Lock the sheet first, so two users opening the editor at the same moment take turns.
186	        sheets.lock(sheetId);
187	        Claim claim = claims.findByIdAndSheetIdAndPersonId(id, sheetId, personId)
188	                .orElseThrow(() -> new NoSuchElementException("No claim " + id + " for person " + personId));
189	        if (claim.getStatus() != ClaimStatus.DRAFT) {
190	            throw new ClaimNotEditableException(claim.getStatus());
191	        }
192	        refuseClosed(sheetId, claim.getDueBy());
193	        if (claim.lockedAgainst(user)) {
194	            throw new ClaimLockedException(claim.getLockedBy());
195	        }
196	        claim.setLockedBy(user);
197	        return claims.saveAndFlush(claim);
198	    }
