200	    /** Cancel a claim's editor: release the user's lock on it; a lock another user holds is kept. */
201	    @Transactional
202	    public Claim unlock(String sheetId, String user, Long personId, Long id) {
203	        person(sheetId, personId);
204	        sheets.lock(sheetId);
205	        Claim claim = claims.findByIdAndSheetIdAndPersonId(id, sheetId, personId)
206	                .orElseThrow(() -> new NoSuchElementException("No claim " + id + " for person " + personId));
207	        if (user.equals(claim.getLockedBy())) {
208	            claim.setLockedBy(null);
209	            claim = claims.saveAndFlush(claim);
