239	    /** Move a claim to a new status, as above; a void, while the sheet's list of void reasons is not
240	     *  empty, needs a reason chosen from it, which the claim keeps and the audit line ends with. */
241	    @Transactional
242	    public Claim changeStatus(String sheetId, String user, Long personId, Long id, ClaimStatus to,
243	            String voidReason) {
244	        Person person = person(sheetId, personId);
245	        // Lock the sheet first, so a claim opened at the same moment elsewhere waits and the claim
246	        // read below is its latest state.
247	        if (to == ClaimStatus.OPEN) {
248	            sheets.lock(sheetId);
249	        }
250	        Claim claim = claim(sheetId, personId, id);
251	        settings.refuseUnless(sheetId, user, switch (to) {
252	            case OPEN -> Permission.OPEN;
253	            case SETTLED -> Permission.SETTLE;
254	            case VOID -> Permission.VOID;
255	            case DRAFT, PENDING -> throw new StatusChangeRefusedException(claim.getStatus(), to);
256	        });
257	        refuseClosed(sheetId, claim.getDueBy());
258	        // A SETTLED claim is voided only by a steward, within the void window of its settlement.
259	        boolean reversing = to == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED;
260	        if (reversing) {
261	            refuseLateOrUnstewardedVoid(sheetId, user, claim);
262	        } else if (!claim.getStatus().canMoveTo(to)) {
263	            throw new StatusChangeRefusedException(claim.getStatus(), to);
264	        }
265	        String reason = voidReason == null || voidReason.isBlank() ? null : voidReason.trim();
266	        if (to == ClaimStatus.VOID) {
267	            refuseUnreasonedVoid(sheetId, reason);
268	        }
269	        if (to == ClaimStatus.SETTLED && claim.openedOrEditedBy(user)) {
270	            throw new OwnClaimSettleRefusedException(user);
271	        }
272	        if (to == ClaimStatus.SETTLED && claim.deferredOn(sheets.today(sheetId))) {
273	            throw new StatusChangeRefusedException(claim.getStatus(), to);
274	        }
275	        // Taken while the claim is still OPEN, so a settled due freezes in the late charge it has
276	        // gathered by then.
277	        BigDecimal due = to == ClaimStatus.SETTLED ? dueOf(sheetId, person, claim) : null;
278	        if (to == ClaimStatus.SETTLED) {
279	            refuseUnproved(sheetId, person, claim, due);
280	        }
281	        if (to == ClaimStatus.OPEN) {
282	            refuseUnnoted(sheetId, person, claim);
283	        }
284	        if (to == ClaimStatus.SETTLED && overClerkLimit(sheetId, user, due)) {
285	            to = ClaimStatus.PENDING;
286	        }
287	        claim.setStatus(to);
288	        if (to == ClaimStatus.SETTLED || to == ClaimStatus.PENDING) {
289	            // Settled one at a time until a bulk settle marks it with its batch.
290	            claim.setBatch(null);
291	        }
292	        if (to == ClaimStatus.OPEN) {
293	            claim.setNumber(nextNumber(sheetId, claim.getDueBy()));
294	            claim.setOpenedBy(user);
295	        } else if (to == ClaimStatus.SETTLED) {
296	            claim.setSettledDue(due);
297	        } else if (to == ClaimStatus.VOID) {
298	            claim.setVoidReason(reason);
299	        }
300	        Claim saved = claims.saveAndFlush(claim);
301	        log(sheetId, user, person, saved);
302	        String event = switch (to) {
303	            case OPEN -> "CLAIM_OPENED";
304	            case PENDING -> "CLAIM_PENDING";
305	            case SETTLED -> "CLAIM_SETTLED";
306	            case VOID -> "CLAIM_VOIDED";
307	            case DRAFT -> throw new IllegalStateException("A claim never returns to DRAFT");
308	        };
309	        String line = line(event, sheetId, user, person, saved, saved.getNumber());
310	        if (to == ClaimStatus.SETTLED) {
311	            line += " due=" + settledDueText(saved);
312	        } else if (reversing) {
313	            line += " reversed=" + settledDueText(saved);
314	        }
315	        if (to == ClaimStatus.VOID && reason != null) {
316	            line += " reason=" + reason;
317	        }
318	        audit.recordOnCommit(line);
319	        if (to == ClaimStatus.SETTLED) {
320	            notifyWatchers(sheetId, user, person, saved);
321	        }
322	        return saved;
323	    }
