334	            throw new DeferRefusedException("A " + claim.getStatus() + " claim cannot be deferred");
335	        }
336	        if (!until.isAfter(sheets.today(sheetId))) {
337	            throw new DeferRefusedException("A claim is deferred to a date after the sheet's today");
338	        }
339	        claim.setDeferredUntil(until);
340	        Claim saved = claims.saveAndFlush(claim);
341	        audit.recordOnCommit(line("CLAIM_DEFERRED", sheetId, user, person, saved, saved.getNumber())
342	                + " until=" + until);
