411	    /** Remind an OPEN or PENDING claim: REMIND is written and the claim's reminded date is the sheet's
412	     *  today. A claim in any other status, or one already reminded on the sheet's today, is refused. */
413	    @Transactional
414	    public Claim remind(String sheetId, String user, Long personId, Long id) {
415	        Person person = person(sheetId, personId);
416	        // Lock the sheet first, so two presses on the same day write one reminder.
417	        sheets.lock(sheetId);
418	        Claim claim = claim(sheetId, personId, id);
419	        LocalDate today = sheets.today(sheetId);
420	        if (!claim.getStatus().isOpen()) {
421	            throw new RemindRefusedException("A " + claim.getStatus() + " claim cannot be reminded");
422	        }
423	        if (today.equals(claim.getRemindedOn())) {
424	            throw new RemindRefusedException("The claim was already reminded on " + today);
425	        }
426	        claim.setRemindedOn(today);
427	        Claim saved = claims.saveAndFlush(claim);
428	        record("REMIND", sheetId, user, person, saved);
429	        return saved;
430	    }
