433	     *  a closed period, is refused. */
434	    @Transactional
435	    public Claim addProof(String sheetId, String user, Long personId, Long id) {
436	        Person person = person(sheetId, personId);
437	        Claim claim = claim(sheetId, personId, id);
438	        refuseClosed(sheetId, claim.getDueBy());
439	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
440	            throw new ProofRefusedException(claim.getStatus());
441	        }
442	        claim.addProof();
443	        Claim saved = claims.saveAndFlush(claim);
444	        audit.recordOnCommit(line("CLAIM_PROOF_ADDED", sheetId, user, person, saved, saved.getNumber())
445	                + " proofs=" + saved.getProofs());
446	        return saved;
447	    }
