449	    /** Comment on a claim in any status: the comment is kept with the user and the sheet's today, and
450	     *  COMMENT_ADDED is written ending with its text. A blank comment is refused. */
451	    @Transactional
452	    public Claim addComment(String sheetId, String user, Long personId, Long id, String text) {
453	        Person person = person(sheetId, personId);
454	        Claim claim = claim(sheetId, personId, id);
455	        String trimmed = text == null ? "" : text.trim();
456	        if (trimmed.isEmpty()) {
457	            throw new CommentRefusedException("A comment cannot be empty");
