540	    private Claim move(String sheetId, String user, Long personId, Long id, Long toPersonId, boolean samePerson) {
541	        Person from = person(sheetId, personId);
542	        Person to = person(sheetId, toPersonId);
543	        // Lock the sheet first, as opening does: a numbered claim takes the next number.
544	        sheets.lock(sheetId);
545	        Claim claim = claim(sheetId, personId, id);
546	        if (!settings.allows(sheetId, user, Permission.REASSIGN)) {
547	            throw new ReassignRefusedException(user);
548	        }
549	        if (!claim.getStatus().canReassign()) {
550	            throw new MoveRefusedException("A " + claim.getStatus() + " claim cannot move to another person");
551	        }
552	        if (!samePerson && from.getId().equals(to.getId())) {
553	            throw new MoveRefusedException("The claim is already " + to.getName() + "'s");
554	        }
555	        if (claim.isCorrection()) {
556	            throw new MoveRefusedException("A correction stays with the person whose claim it corrects");
557	        }
558	        refuseClosed(sheetId, claim.getDueBy());
559	        refuseRetired(to, claim.getDate());
560	        claim.setPersonId(to.getId());
561	        if (claim.getNumber() != null) {
562	            String old = claim.getNumber();
563	            claim.setNumber(nextNumber(sheetId, claim.getDueBy()));
564	            claims.retireNumber(sheetId, old);
565	        }
566	        claim.unbind();
567	        claims.saveAndFlush(claim);
568	        claims.relist(claim.getId());
569	        Claim saved = claim(sheetId, to.getId(), id);
570	        audit.recordOnCommit(line("CLAIM_REASSIGNED", sheetId, user, to, saved, saved.getNumber())
571	                + " from=" + from.getName() + " to=" + to.getName());
572	        return saved;
573	    }
