576	     *  statement bound it to stays bound; its period, which follows its due-by, and its number
577	     *  stay too. Anyone but a steward, a claim that is not OPEN or PENDING, a claim whose due-by falls
578	     *  in a closed period, or a new date after its person's retirement, is refused. */
579	    @Transactional
580	    public Claim redate(String sheetId, String user, Long personId, Long id, LocalDate date) {
581	        Person person = person(sheetId, personId);
582	        // Lock the sheet first, as opening does: the claim may take the next number.
583	        sheets.lock(sheetId);
584	        Claim claim = claim(sheetId, personId, id);
585	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
586	            throw new RedateForbiddenException(user);
587	        }
588	        if (!claim.getStatus().isOpen()) {
589	            throw new RedateRefusedException("A " + claim.getStatus() + " claim cannot be re-dated");
590	        }
591	        refuseClosed(sheetId, claim.getDueBy());
592	        refuseRetired(person, date);
593	        LocalDate old = claim.getDate();
594	        claim.setDate(date);
595	        Claim saved = claims.saveAndFlush(claim);
596	        audit.recordOnCommit(line("CLAIM_REDATED", sheetId, user, person, saved, saved.getNumber())
597	                + " old=" + old + " new=" + date);
598	        return saved;
599	    }
