695	    /** The number a claim opened now takes: under period numbering (set, and the sheet's today on or
696	     *  after it) the next within the period its due-by falls in, <period>-<n>, or X-<n> when it falls
697	     *  in none; otherwise the sheet's next sheet-wide number. Taken with the sheet locked. */
698	    private String nextNumber(String sheetId, LocalDate date) {
699	        if (!periodNumbering(sheetId)) {
700	            return String.valueOf(sheets.nextClaimNumber(sheetId));
701	        }
702	        String prefix = periodPrefixOf(sheetId, date);
703	        long last = Stream.concat(claims.numbers(sheetId).stream(), claims.retiredNumbers(sheetId).stream())
704	                .filter(number -> number.startsWith(prefix))
705	                .map(number -> number.substring(prefix.length()))
706	                .filter(n -> n.matches("\\d{1,18}"))
707	                .mapToLong(Long::parseLong)
708	                .max().orElse(0);
709	        return prefix + (last + 1);
710	    }
