782	    /** The date a claim is overdue after: its due-by plus the grace days in force on its date for the
783	     *  person's grade in force on its date (as they stood at the end of a day; null: as they stand now). */
784	    public LocalDate overdueFrom(String sheetId, Person person, Claim claim, LocalDate asOf) {
785	        String grade = grades.gradeOn(person.getId(), claim.getDate(), asOf);
786	        return claim.getDueBy().plusDays(settings.graceFor(sheetId, grade, claim.getDate(), asOf));
787	    }
788	
789	    /** The late charge on a claim with a figure: none unless it is OPEN or PENDING and overdue (its due-by
790	     *  plus its grace, see overdueFrom, is before the sheet's today) or a correction, else the late percent of
791	     *  the figure for every 30-day boundary it is overdue past (its due-by plus its grace plus 30, 60, 90 ...
792	     *  days), compounding: the late percent in force on that boundary date of the figure plus the charges
793	     *  of the boundaries before it, rounded to two decimals as the claim's date decides (see roundingOf), the
794	     *  charges added up. Never bound by a statement: it follows the
795	     *  sheet's today. Whether the claim counts as open is given, so a re-settle can charge a SETTLED
796	     *  claim as if it were still OPEN. */
797	    private BigDecimal lateChargeOf(String sheetId, Person person, Claim claim, BigDecimal figure, boolean open,
798	            LocalDate asOf) {
799	        BigDecimal none = BigDecimal.ZERO.setScale(2);
800	        if (!open || claim.isCorrection()) {
801	            return none;
802	        }
803	        LocalDate from = overdueFrom(sheetId, person, claim, asOf);
804	        long days = ChronoUnit.DAYS.between(from, todayOr(sheetId, asOf));
805	        if (days < 30) {
806	            return none;
807	        }
808	        RoundingMode rounding = roundingOf(sheetId, claim, asOf);
809	        BigDecimal charge = none;
810	        for (long boundary = 1; boundary <= days / 30; boundary++) {
811	            BigDecimal pct = settings.latePct(sheetId, from.plusDays(30 * boundary), asOf);
812	            if (pct.signum() != 0) {
813	                charge = charge.add(figure.add(charge).multiply(pct).movePointLeft(2).setScale(2, rounding));
814	            }
815	        }
816	        return charge;
817	    }
