819	    /** The due on a claim at the rate in force on the claim's date for the person's grade in force
820	     *  on the claim's date: amount times rate
821	     *  divided by 100, rounded to two decimals as the claim's date decides (see roundingOf); the floor is
822	     *  not applied here (see dueOf); null when no rate applies. */
823	    private BigDecimal liveFigureOf(String sheetId, Person person, Claim claim, LocalDate asOf,
824	            RateOverride override) {
825	        BigDecimal amount = claim.getAmount();
826	        RoundingMode rounding = roundingOf(sheetId, claim, asOf);
827	        String grade = grades.gradeOn(person.getId(), claim.getDate(), asOf);
828	        Optional<BigDecimal> inForce = override != null && override.grade().equals(grade) ? Optional.of(override.rate())
829	                : rates.rateOn(sheetId, grade, claim.getDate(), asOf).map(Rate::getRate);
830	        return inForce
831	                .map(rate -> amount.multiply(rate).movePointLeft(2).setScale(2, rounding))
832	                .orElse(null);
833	    }
