839	    /** What a rate preview finds: how many claims would show a different due, and the sum of the
840	     *  differences (new due minus current due). */
841	    public record RatePreview(int count, BigDecimal diff) {
842	    }
843	
844	    /** How the OPEN and PENDING claims of people on a grade (the grade in force on the claim's date)
845	     *  would change were the rate given the grade's rate on every date: how many would show a different
846	     *  due and the sum of the differences (a due of n/a counts as 0.00). A claim a statement binds keeps
847	     *  its figure. Nothing is saved. */
848	    @Transactional(readOnly = true)
849	    public RatePreview previewRate(String sheetId, String grade, BigDecimal rate) {
850	        RateOverride override = new RateOverride(grade, rate);
851	        Map<Long, Person> byId = people.findBySheetIdOrderByIdAsc(sheetId).stream()
852	                .collect(Collectors.toMap(Person::getId, person -> person));
853	        int count = 0;
854	        BigDecimal diff = BigDecimal.ZERO.setScale(2);
855	        for (Claim claim : claims.findBySheetIdOrderByListedDesc(sheetId)) {
856	            Person person = byId.get(claim.getPersonId());
857	            if (person == null || !claim.getStatus().isOpen()
858	                    || !grade.equals(grades.gradeOn(person.getId(), claim.getDate(), null))) {
859	                continue;
860	            }
861	            BigDecimal now = dueOf(sheetId, person, claim, null);
862	            BigDecimal then = dueOf(sheetId, person, claim, null, override);
863	            BigDecimal was = now == null ? BigDecimal.ZERO : now;
864	            BigDecimal will = then == null ? BigDecimal.ZERO : then;
865	            if ((now == null) != (then == null) || was.compareTo(will) != 0) {
866	                count++;
867	                diff = diff.add(will.subtract(was));
868	            }
869	        }
870	        return new RatePreview(count, diff.setScale(2, RoundingMode.HALF_UP));
871	    }
