898	    /** A claim whose due is above the proof threshold in force on its date (its person's grade's in
899	     *  force then when one is set, else the sheet's) cannot be settled or approved while it has no
900	     *  proofs; a due of n/a, or no threshold, asks for none. */
901	    private void refuseUnproved(String sheetId, Person person, Claim claim, BigDecimal due) {
902	        String grade = grades.gradeOn(person.getId(), claim.getDate());
903	        BigDecimal threshold = settings.proofThresholdFor(sheetId, grade, claim.getDate());
904	        if (claim.getProofs() == 0 && threshold != null && due != null && due.compareTo(threshold) > 0) {
905	            throw new ProofRequiredException(due, threshold);
906	        }
907	    }
908	
909	    /** A claim whose due is above the note threshold in force on its date cannot be opened while its
910	     *  note is empty; a due of n/a, or no threshold, asks for none. */
911	    private void refuseUnnoted(String sheetId, Person person, Claim claim) {
912	        BigDecimal threshold = settings.noteThreshold(sheetId, claim.getDate());
913	        if (threshold == null || (claim.getNote() != null && !claim.getNote().isBlank())) {
914	            return;
915	        }
916	        BigDecimal due = dueOf(sheetId, person, claim);
917	        if (due != null && due.compareTo(threshold) > 0) {
918	            throw new NoteRequiredException(due, threshold);
919	        }
920	    }
921	
922	    /** A negative amount (a correction) must name the number of a SETTLED claim of the same person;
923	     *  any other amount names none. */
924	    private void refuseBadCorrection(String sheetId, Long personId, BigDecimal amount, String corrects) {
925	        if (amount.signum() >= 0) {
926	            if (corrects != null) {
927	                throw new CorrectionRefusedException("Only a negative amount corrects a claim");
928	            }
929	            return;
930	        }
931	        if (corrects == null) {
932	            throw new CorrectionRefusedException("A negative amount must name the claim it corrects");
933	        }
934	        boolean settled = claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
935	                .map(c -> c.getStatus() == ClaimStatus.SETTLED).orElse(false);
936	        if (!settled) {
937	            throw new CorrectionRefusedException("No SETTLED claim " + corrects + " of this person to correct");
938	        }
939	    }
940	
941	    /** Whether a claim on the sheet other than the given one (null: any) already uses the reference,
942	     *  without regard to case; a null reference is never in use. */
943	    public boolean refInUse(String sheetId, String ref, Long exceptId) {
944	        return ref != null && claims.refInUse(sheetId, Claim.keyOf(ref), exceptId);
945	    }
946	
947	    /** A reference another claim on the sheet already uses cannot be given again. */
948	    private void refuseRefInUse(String sheetId, String ref, Long exceptId) {
949	        if (refInUse(sheetId, ref, exceptId)) {
950	            throw new RefInUseException("The reference " + ref + " is already used on the sheet");
951	        }
952	    }
953	
954	    /** A claim whose due-by falls inside a closed period cannot be added, edited, opened, settled or voided. */
955	    private void refuseClosed(String sheetId, LocalDate dueBy) {
956	        if (periods.closedOn(sheetId, dueBy)) {
957	            throw new PeriodClosedException("A claim due by " + dueBy + " falls in a closed period");
958	        }
959	    }
960	
961	    /** A claim dated after its person's retirement date cannot be added or moved there. */
962	    private static void refuseRetired(Person person, LocalDate date) {
963	        if (person.isRetired() && date.isAfter(person.getRetiredFrom())) {
964	            throw new PersonRetiredException(person.getName(), person.getRetiredFrom(), date);
965	        }
966	    }
967	
968	    private Person person(String sheetId, Long personId) {
969	        return people.findByIdAndSheetId(personId, sheetId)
970	                .orElseThrow(() -> new NoSuchElementException("No person " + personId + " on sheet " + sheetId));
971	    }
972	
973	    /** One NOTIFY line for each user watching the claim's person, in the order they started watching. */
974	    private void notifyWatchers(String sheetId, String user, Person person, Claim claim) {
975	        for (PersonWatch watch : watches.findByPersonIdOrderByIdAsc(person.getId())) {
976	            audit.recordOnCommit("NOTIFY sheet=" + sheetId + " by=" + user + " user=" + watch.getUser()
977	                    + " person=" + person.getName() + " number=" + claim.getNumber());
978	        }
979	    }
980	
981	    private void record(String event, String sheetId, String user, Person person, Claim claim) {
982	        record(event, sheetId, user, person, claim, claim.getNumber());
983	    }
984	
985	    /** One audit line about a claim; a claim with a number carries it at the end. */
986	    private void record(String event, String sheetId, String user, Person person, Claim claim, String number) {
987	        audit.recordOnCommit(line(event, sheetId, user, person, claim, number));
988	    }
989	
990	    private static String line(String event, String sheetId, String user, Person person, Claim claim, String number) {
991	        return event + " sheet=" + sheetId + " by=" + user + " person=" + person.getName()
992	                + " amount=" + claim.getAmount().toPlainString() + " date=" + claim.getDate()
993	                + (number != null ? " number=" + number : "");
994	    }
995	
996	    private static BigDecimal scaled(BigDecimal amount) {
997	        return amount.setScale(2, RoundingMode.UNNECESSARY);
998	    }
999	
1000	    /** A claim number as typed: trimmed, null when blank. */
1001	    private static String numberOf(String number) {
1002	        return number == null || number.isBlank() ? null : number.trim();
1003	    }
1004	
1005	    /** Tags as typed, comma separated: each trimmed and in lower case, blanks and repeats dropped,
1006	     *  sorted. */
1007	    public static SortedSet<String> tagsOf(String tags) {
1008	        SortedSet<String> out = new TreeSet<>();
1009	        if (tags != null) {
1010	            for (String tag : tags.split(",")) {
1011	                if (!tag.isBlank()) {
1012	                    out.add(tag.trim().toLowerCase(Locale.ROOT));
1013	                }
1014	            }
1015	        }
1016	        return out;
1017	    }
1018	
1019	    /** Every tag ever used on the sheet, sorted. */
1020	    public List<String> tagsUsed(String sheetId) {
1021	        return claims.tagsUsed(sheetId);
1022	    }
1023	
1024	    /** Keep the claim's tags on the sheet's list of the tags ever used. */
1025	    private void useTags(String sheetId, Claim claim) {
1026	        claim.getTags().forEach(tag -> claims.useTag(sheetId, tag));
1027	    }
1028	
1029	    /** An external reference as typed: trimmed, null when blank. */
1030	    public static String refOf(String ref) {
1031	        return ref == null || ref.isBlank() ? null : ref.trim();
1032	    }
1033	
1034	    private static String noteOf(String note) {
1035	        return note == null ? "" : note.trim();
1036	    }
1037	
1038	    /** The terms in business days a claim of the person dated on a date takes: the person's own, else their
1039	     *  grade's in force then, else the sheet's. */
1040	    private int termsFor(String sheetId, Person person, LocalDate on) {
1041	        return person.getTerms() != null ? person.getTerms()
1042	                : settings.termsFor(sheetId, grades.gradeOn(person.getId(), on), on);
1043	    }
1044	}
